// RoleBinding One role granted to a subject, globally or in one org.
type RoleBinding struct {
	// CreatedAt Creation time.
	CreatedAt time.Time `json:"createdAt"`

	// Id Binding id.
	Id openapi_types.UUID `json:"id"`

	// OrgId Org the role applies to; null for global.
	OrgId *openapi_types.UUID `json:"orgId"`

	// Role A role. admin is everything; org-admin everything in its org except global-only actions; operator certificates, credentials, accounts, clients, issue and renew; viewer read-only; auditor viewer plus the audit log.
	Role Role `json:"role"`

	// Subject User id
	Subject string `json:"subject"`

	// SubjectLabel User display name
	SubjectLabel string `json:"subjectLabel"`

	// SubjectType What a binding's subject names.
	SubjectType SubjectType `json:"subjectType"`
}

// RoleBindingInput A new role binding.
type RoleBindingInput struct {
	// OrgId Org scope; omit or null for global.
	OrgId *openapi_types.UUID `json:"orgId"`

	// Role A role. admin is everything; org-admin everything in its org except global-only actions; operator certificates, credentials, accounts, clients, issue and renew; viewer read-only; auditor viewer plus the audit log.
	Role Role `json:"role"`

	// Subject User id
	Subject string `json:"subject"`

	// SubjectType What a binding's subject names.
	SubjectType SubjectType `json:"subjectType"`
}

// RoleBindingList Role bindings.
type RoleBindingList struct {
	// Items Bindings
	Items []RoleBinding `json:"items"`
}

// SchemaEntry One registered pluggable type.
type SchemaEntry struct {
	// Aliases Other codes that select this type; used by search.
	Aliases *[]string `json:"aliases,omitempty"`

	// Code Stable type code, for example cloudflare.
	Code string `json:"code"`

	// Name Display name.
	Name string `json:"name"`

	// Schema JSON Schema for the type's configuration. Fields with secret true are write-only.
	Schema map[string]interface{} `json:"schema"`
}

// SettingsSection A settings section with its schema.
type SettingsSection struct {
	// Schema JSON Schema (draft 2020-12) of the value; the UI renders the form from it.
	Schema map[string]interface{} `json:"schema"`

	// Section Section name.
	Section string `json:"section"`

	// Stored The raw value actually saved for this section, before built-in defaults are filled in; null when the section has never been saved. Lets a client tell "never configured" apart from "explicitly set to the built-in value" (value alone cannot, since it always looks concrete once a default is filled in). Secret properties are never included here.
	Stored *SettingsValue `json:"stored"`

	// StoredSecrets Names of the section's secret properties that currently hold a value. Secret values are never returned; send "__unchanged__" to keep one, "" to clear it.
	StoredSecrets []string `json:"storedSecrets"`

	// Value The section's effective value — its own stored value, or the section's built-in default when it has never been saved. Secret properties are never included here.
	Value SettingsValue `json:"value"`
}

// SettingsValue A settings section value; its shape is defined by the section schema.
type SettingsValue map[string]interface{}

// SetupRequest First-run wizard input.
type SetupRequest struct {
	// AdminPassword New local admin password, at least 12 characters.
	AdminPassword string `json:"adminPassword"`

	// BaseUrl Public URL of this CertForge instance, for example https://certs.example.com.
	BaseUrl string `json:"baseUrl"`

	// OrgName Display name of the first org.
	OrgName string `json:"orgName"`

	// OrgSlug URL-safe identifier of the first org.
	OrgSlug string `json:"orgSlug"`
}

// SetupStatus First-run state.
type SetupStatus struct {
	// NeedsSetup True until POST /setup/complete succeeds.
	NeedsSetup bool `json:"needsSetup"`
}

// Site A location within an org, used as a filter.
type Site struct {
	// CreatedAt Creation time.
	CreatedAt time.Time `json:"createdAt"`

	// Id Site id.
	Id openapi_types.UUID `json:"id"`

	// Name Name
	Name string `json:"name"`

	// OrgId Owning org.
	OrgId openapi_types.UUID `json:"orgId"`
}

// SiteInput A site's name.
type SiteInput struct {
	// Name Name
	Name string `json:"name"`
}

// SiteList Sites of an org.
type SiteList struct {
	// Items Sites sorted by name.
	Items []Site `json:"items"`
}

// Source Level an effective value came from; default means the built-in value.
type Source string

// SubjectType What a binding's subject names.
type SubjectType string

// User A CertForge user.
type User struct {
	// DisplayName Name shown in the UI.
	DisplayName string `json:"displayName"`

	// Id User id.
	Id openapi_types.UUID `json:"id"`

	// LocalAdmin True for the break-glass local admin.
	LocalAdmin bool `json:"localAdmin"`
}

// UserDetail A user as shown in Settings → Access.
type UserDetail struct {
	// CreatedAt First sign-in or creation time.
	CreatedAt time.Time `json:"createdAt"`

	// Disabled Disabled users cannot sign in and their API keys stop working.
	Disabled bool `json:"disabled"`

	// DisplayName Name from the identity provider
	DisplayName string `json:"displayName"`

	// Email Email from the identity provider.
	Email *string `json:"email"`

	// Groups Groups from the user's last OIDC login.
	Groups []string `json:"groups"`

	// Id User id.
	Id openapi_types.UUID `json:"id"`

	// LastLogin Last successful sign-in.
	LastLogin *time.Time `json:"lastLogin"`

	// LocalAdmin True for the break-glass local admin.
	LocalAdmin bool `json:"localAdmin"`

	// OidcIssuer Issuer that authenticated the user; null for the local admin.
	OidcIssuer *string `json:"oidcIssuer"`

	// OidcSubject Subject at the issuer.
	OidcSubject *string `json:"oidcSubject"`
}

// UserList All users.
type UserList struct {
	// Items Users sorted by display name.
	Items []UserDetail `json:"items"`
}

// UserUpdate Changes to a user.
type UserUpdate struct {
	// Disabled true disables the user and revokes their sessions.
	Disabled bool `json:"disabled"`
}

// VerificationRule How to prove control of the names this rule matches. First match wins.
type VerificationRule struct {
	// CnameAliasZone Zone that _acme-challenge is CNAMEd into; checked before validation.
	CnameAliasZone *string `json:"cnameAliasZone,omitempty"`

	// DnsCredentialId DNS credential; required for dns-01.
	DnsCredentialId *openapi_types.UUID `json:"dnsCredentialId,omitempty"`

	// Match * (every name), *.zone (names one label below zone, and *.zone itself), or zone (the zone, its subdomains and wildcards).
	Match string `json:"match"`

	// Method Verification method.
	Method VerificationRuleMethod `json:"method"`

	// PropagationSeconds Propagation timeout override.
	PropagationSeconds *int `json:"propagationSeconds,omitempty"`

	// Resolvers Resolvers for propagation checks.
	Resolvers *[]string `json:"resolvers,omitempty"`
}

// VerificationRuleMethod Verification method.
type VerificationRuleMethod string

